package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseP3MigrationTest extends MigrationTestSupport {
 @Test void clinicalBoundaryRollsBackAndRetriesWithoutImportingLegacyClinicalClaims(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_p3_upgrade_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("75").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));try{long users=db.queryForObject("SELECT count(*) FROM users",Long.class),consultations=db.queryForObject("SELECT count(*) FROM consultation_requests",Long.class);db.execute("CREATE TABLE clinic_notes(synthetic_conflict INTEGER)");assertThatThrownBy(()->Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate()).isInstanceOf(Exception.class);assertThat(db.queryForObject("SELECT count(*) FROM information_schema.tables WHERE table_schema=? AND table_name='clinic_encounters'",Integer.class,schema)).isZero();db.execute("DROP TABLE clinic_notes");Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate();assertThat(db.queryForObject("SELECT count(*) FROM users",Long.class)).isEqualTo(users);assertThat(db.queryForObject("SELECT count(*) FROM consultation_requests",Long.class)).isEqualTo(consultations);assertThat(db.queryForObject("SELECT count(*) FROM clinic_messages",Long.class)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM clinic_record_policies",Long.class)).isZero();}finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}}
}
